import random, json
random.seed(11)
comp={'A':'U','U':'A','G':'C','C':'G'}
def hp(s,loop): return s+loop+''.join(comp[b] for b in reversed(s))
# stable loop/closing pair combos (loop, 5' stem bases) with closing pair preferred
loop_stem=[('UUCG','CG'),('UUCG','CC'),('GAAA','CG'),('GAAA','GG'),('GCAA','CG'),('UUUA','GG'),('UUCG','GG'),('GAAA','CC'),('AUUU','GG'),('CUUC','GG')]
linkers=['A','U']
cands=set()
for l1,s1 in loop_stem:
    for l2,s2 in loop_stem:
        for lk in linkers:
            full=hp(s1,l1)+lk+hp(s2,l2)
            cands.add(full)
cands=sorted(cands)
random.shuffle(cands)
out=[]
for c in cands:
    if any(c[i:i+4]==c[i]*4 for i in range(len(c)-3)): continue
    out.append(c)
    if len(out)>=48: break
print(len(out)); print(json.dumps(out))
